SETTINGS_DATA.carried.push({"rows":[{"section":"AdShield","key":"twitchVodRewind","byId":false,"name":"Watch from earlier (stream rewind)","desc":"Adds a \"Rewind\" button by the player controls that lets you jump back to before you opened the tab — from when you joined, 30 minutes back, or the very start — and watch what you missed in Twitch's normal player. Works only when the streamer saves past broadcasts (VODs); the button appears only on streams where it's available. No recording, no extra memory. On by default."},{"section":"AdShield","key":"twitchRewind","byId":false,"name":"Twitch local rewind (DVR)","desc":"Adds 10s / 30s / 1m / 5m rewind buttons and a scrub timeline beside Twitch's volume control, plus speed (1–2×, eases back to live) and keyboard control (←/→ seek 10s, ,/. frame-step). Delayed playback keeps running until you press LIVE. It records the live stream into your computer's memory while the tab is open, so it uses noticeably more RAM and CPU (and more with a longer buffer or higher stream quality). It cannot recover video from before the tab started watching. Opt-in."}],"defaults":{"twitchRewind":false,"twitchVodRewind":true},"popupDefaults":{"twitchRewind":false,"twitchRewindMinutes":5,"twitchVodRewind":true},"siteOverrideScope":{"page":["twitchRewind","twitchVodRewind"]}});
